    {'name': 'Miskolc', 'lat': 48.1035, 'lng': 20.7784, 'cars': 6},
    {'name': 'Pecs', 'lat': 46.0727, 'lng': 18.2323, 'cars': 5},
    {'name': 'Gyor', 'lat': 47.6875, 'lng': 17.6504, 'cars': 5},
    {'name': 'Nyiregyhaza', 'lat': 47.9554, 'lng': 21.7167, 'cars': 4},
    {'name': 'Kecskemet', 'lat': 46.8964, 'lng': 19.6897, 'cars': 4},
    {'name': 'Szekesfehervar', 'lat': 47.1860, 'lng': 18.4221, 'cars': 4},
    {'name': 'Szombathely', 'lat': 47.2307, 'lng': 16.6218, 'cars': 3},
    {'name': 'Szolnok', 'lat': 47.1621, 'lng': 20.1825, 'cars': 3},
    {'name': 'Eger', 'lat': 47.9025, 'lng': 20.3772, 'cars': 3},
    {'name': 'Veszprem', 'lat': 47.0933, 'lng': 17.9115, 'cars': 3},
    {'name': 'Bekescsaba', 'lat': 46.6834, 'lng': 21.0887, 'cars': 2},
    {'name': 'Zalaegerszeg', 'lat': 46.8417, 'lng': 16.8416, 'cars': 2},
    {'name': 'Sopron', 'lat': 47.6817, 'lng': 16.5845, 'cars': 2},
    {'name': 'Kaposvar', 'lat': 46.3594, 'lng': 17.7968, 'cars': 2},
    {'name': 'Tatabanya', 'lat': 47.5863, 'lng': 18.4049, 'cars': 2},
    {'name': 'Dunaujvaros', 'lat': 46.9619, 'lng': 18.9355, 'cars': 2},
    {'name': 'Hodmezovasarhely', 'lat': 46.4181, 'lng': 20.3300, 'cars': 2}
]

UNIT_TYPES = [
    {'code': 'JAR', 'name': 'Jarorauto', 'speed': 0.0008},
    {'code': 'GYR', 'name': 'Gyorsreagalasu', 'speed': 0.0015},
    {'code': 'KOZ', 'name': 'Kozlekedesi', 'speed': 0.0012},
    {'code': 'BUN', 'name': 'Bunugyi', 'speed': 0.0006},
    {'code': 'TEK', 'name': 'TEK Egyseg', 'speed': 0.002},
    {'code': 'MOT', 'name': 'Motoros', 'speed': 0.0018}
]

STATUS_TYPES = [
    {'code': 'PATROL', 'name': 'Jarorozesben', 'color': '#22c55e'},
    {'code': 'RESPOND', 'name': 'Riasztasra Megy', 'color': '#ef4444'},
    {'code': 'STANDBY', 'name': 'Keszenleti Helyen', 'color': '#3b82f6'},
    {'code': 'RETURN', 'name': 'Visszateroben', 'color': '#f59e0b'},
    {'code': 'BREAK', 'name': 'Szunetben', 'color': '#6b7280'}
]

police_cars = {}
incidents = []
lock = threading.Lock()

def generate_car_id(city_code, unit_type, number):
    return f"{city_code}-{unit_type}-{number:03d}"

def initialize_cars():
    global police_cars
    with lock:
        police_cars = {}
        car_number = 1
        for city in CITIES:
            city_code = city['name'][:3].upper()
            for i in range(city['cars']):
                unit_type = random.choice(UNIT_TYPES)
                status = random.choice(STATUS_TYPES)
                angle = random.uniform(0, 2 * math.pi)
                distance = random.uniform(0.005, 0.03)
                lat = city['lat'] + distance * math.sin(angle)
                lng = city['lng'] + distance * math.cos(angle)
                car_id = generate_car_id(city_code, unit_type['code'], car_number)
                police_cars[car_id] = {
                    'id': car_id,
                    'lat': lat,
                    'lng': lng,
                    'city': city['name'],
                    'unit_type': unit_type,
                    'status': status,
                    'heading': random.uniform(0, 360),
                    'speed': unit_type['speed'],
                    'target_lat': None,
                    'target_lng': None,
                    'last_update': datetime.now().isoformat(),
                    'officer_count': random.randint(1, 3),
                    'shift_start': f"{random.randint(6, 22):02d}:00",
                    'fuel_level': random.randint(40, 100),
                    'radio_channel': f"CH-{random.randint(1, 12)}"
                }
                car_number += 1

def update_car_positions():
    while True:
        with lock:
            for car_id, car in police_cars.items():
                if car['status']['code'] == 'STANDBY':
                    continue
                if car['target_lat'] and car['target_lng']:
                    dx = car['target_lng'] - car['lng']
                    dy = car['target_lat'] - car['lat']
                    dist = math.sqrt(dx*dx + dy*dy)
                    if dist < 0.001:
                        car['target_lat'] = None
                        car['target_lng'] = None
                        if car['status']['code'] == 'RESPOND':
                            car['status'] = next(s for s in STATUS_TYPES if s['code'] == 'PATROL')
                    else:
                        car['heading'] = math.degrees(math.atan2(dx, dy))
                        speed = car['speed'] * (1.5 if car['status']['code'] == 'RESPOND' else 1.0)
                        car['lat'] += (dy / dist) * speed
                        car['lng'] += (dx / dist) * speed
                else:
                    if random.random() < 0.02:
                        car['heading'] += random.uniform(-45, 45)
                    rad = math.radians(car['heading'])
                    speed = car['speed'] * random.uniform(0.5, 1.5)
                    new_lat = car['lat'] + speed * math.cos(rad)
                    new_lng = car['lng'] + speed * math.sin(rad)
                    city = next(c for c in CITIES if c['name'] == car['city'])
                    max_dist = 0.05
                    if abs(new_lat - city['lat']) < max_dist and abs(new_lng - city['lng']) < max_dist:
                        car['lat'] = new_lat
                        car['lng'] = new_lng
                    else:
                        car['heading'] = math.degrees(math.atan2(city['lng'] - car['lng'], city['lat'] - car['lat']))
                if random.random() < 0.002:
                    available_statuses = [s for s in STATUS_TYPES if s['code'] != 'RESPOND']
                    car['status'] = random.choice(available_statuses)
                car['fuel_level'] = max(10, car['fuel_level'] - random.uniform(0, 0.1))
                car['last_update'] = datetime.now().isoformat()
        time.sleep(1)

def generate_incidents():
    while True:
        time.sleep(random.uniform(10, 30))
        with lock:
            if len(incidents) < 15:
                city = random.choice(CITIES)
                angle = random.uniform(0, 2 * math.pi)
                distance = random.uniform(0.005, 0.025)
                incident = {
                    'id': str(uuid.uuid4())[:8],
                    'lat': city['lat'] + distance * math.sin(angle),
                    'lng': city['lng'] + distance * math.cos(angle),
                    'city': city['name'],
                    'type': random.choice(['Kozlekedesi baleset', 'Betorolopas', 'Hangos zaj panasz', 'Gyanus szemely', 'Veszelyeztetes', 'Rablasi kiserlet', 'Vandalizmus', 'Garazzdasag']),
                    'priority': random.choice(['LOW', 'MEDIUM', 'HIGH', 'CRITICAL']),
                    'created_at': datetime.now().isoformat(),
                    'status': 'OPEN',
                    'assigned_unit': None
                }
                incidents.append(incident)
                available_cars = [c for c in police_cars.values() if c['status']['code'] in ['PATROL', 'STANDBY'] and c['city'] == city['name']]
                if available_cars:
                    closest_car = min(available_cars, key=lambda c: math.sqrt((c['lat'] - incident['lat'])**2 + (c['lng'] - incident['lng'])**2))
                    closest_car['target_lat'] = incident['lat']
                    closest_car['target_lng'] = incident['lng']
                    closest_car['status'] = next(s for s in STATUS_TYPES if s['code'] == 'RESPOND')
                    incident['assigned_unit'] = closest_car['id']
                    incident['status'] = 'ASSIGNED'

def cleanup_incidents():
    while True:
        time.sleep(60)
        with lock:
            current_time = datetime.now()
            for incident in incidents[:]:
                if incident['status'] == 'ASSIGNED':
                    incident['status'] = 'RESOLVED'
                elif incident['status'] == 'RESOLVED':
                    incidents.remove(incident)

@app.route('/')
def index():
    return send_from_directory('static', 'index.html')

@app.route('/static/<path:filename>')
def serve_static(filename):
    return send_from_directory('static', filename)

@app.route('/api/cars')
def get_cars():
    with lock:
        return jsonify({
            'cars': list(police_cars.values()),
            'timestamp': datetime.now().isoformat(),
            'total_count': len(police_cars)
        })

@app.route('/api/cars/<car_id>')
def get_car(car_id):
    with lock:
        if car_id in police_cars:
            return jsonify(police_cars[car_id])
        return jsonify({'error': 'Car not found'}), 404

@app.route('/api/incidents')
def get_incidents():
    with lock:
        return jsonify({
            'incidents': incidents,
            'timestamp': datetime.now().isoformat(),
            'total_count': len(incidents)
        })

@app.route('/api/stats')
def get_stats():
    with lock:
        status_counts = {}
        for car in police_cars.values():
            status = car['status']['code']
            status_counts[status] = status_counts.get(status, 0) + 1
        city_counts = {}
        for car in police_cars.values():
            city = car['city']
            city_counts[city] = city_counts.get(city, 0) + 1
        incident_counts = {'OPEN': 0, 'ASSIGNED': 0, 'RESOLVED': 0}
        for incident in incidents:
            incident_counts[incident['status']] = incident_counts.get(incident['status'], 0) + 1
        return jsonify({
            'total_cars': len(police_cars),
            'status_distribution': status_counts,
            'city_distribution': city_counts,
            'incident_counts': incident_counts,
            'timestamp': datetime.now().isoformat()
        })

@app.route('/api/dispatch', methods=['POST'])
def dispatch_car():
    data = request.get_json()
    car_id = data.get('car_id')
    target_lat = data.get('lat')
    target_lng = data.get('lng')
    with lock:
        if car_id in police_cars:
            police_cars[car_id]['target_lat'] = target_lat
            police_cars[car_id]['target_lng'] = target_lng
            police_cars[car_id]['status'] = next(s for s in STATUS_TYPES if s['code'] == 'RESPOND')
            return jsonify({'success': True, 'message': f'Egyseg {car_id} kikuldetven'})
        return jsonify({'error': 'Egyseg nem talalhato'}), 404

@app.route('/api/cities')
def get_cities():
    return jsonify({'cities': CITIES})

if __name__ == '__main__':
    initialize_cars()
    position_thread = threading.Thread(target=update_car_positions, daemon=True)
    position_thread.start()
    incident_thread = threading.Thread(target=generate_incidents, daemon=True)
    incident_thread.start()
    cleanup_thread = threading.Thread(target=cleanup_incidents, daemon=True)
    cleanup_thread.start()
    app.run(host='0.0.0.0', port=5000, debug=False, threaded=True)

